                .replaceAll("<span[^>]*>", "").replaceAll("</span>", "")
                .replaceAll("<pre>", "").replaceAll("</pre>", "")
                .replaceAll("&nbsp;", " ").replaceAll("&gt;", ">")
                .replaceAll("&amp;", "&").replaceAll("&lt;", "<")
